// model_params 読込失敗時のデフォルト値（Phase1 初期値）
const defaults = {
  w1: 0.10, w2: 0.12, w3: 0.08, w4: 0.16, w5: 0.16, w6: 0.13, w7: 0.20, w8: 0.05,
  sigma: 0.55,
  epsilon: 0.20,
  pstar: { gadget: 12000, stationery: 5000, restaurant_supply: 15000, beauty_salon: 20000, massage: 18000 }
};
const params = JSON.parse(JSON.stringify(defaults));
try {
  const rows = $('Read model_params').all().map(i => i.json).filter(r => r && !r.error);
  if (rows.length) {
    const r = rows[rows.length - 1]; // 最新1行
    for (const k of ['w1','w2','w3','w4','w5','w6','w7','w8','sigma','epsilon']) {
      if (r[k] !== undefined && r[k] !== '' && isFinite(Number(r[k]))) params[k] = Number(r[k]);
    }
    for (const c of ['gadget','stationery','restaurant_supply','beauty_salon','massage']) {
      const key = 'pstar_' + c;
      if (r[key] !== undefined && r[key] !== '' && isFinite(Number(r[key]))) params.pstar[c] = Number(r[key]);
    }
  }
} catch (e) { /* デフォルト値で続行 */ }

// posted_items: 過去60日の itemCode 一覧
// append-only方式のため同一itemCodeが複数行あり得る。itemCodeで集約し、最新のlast_posted_atを採用（出現回数=times_posted相当）。旧スキーマのdate列にもフォールバック対応
let postedCodes = [];
try {
  const cutoff = Date.now() - 60 * 86400000;
  const latest = {};
  for (const i of $('Read posted_items').all()) {
    const r = i.json;
    if (!r || !r.itemCode) continue;
    const ds = r.last_posted_at || r.date || '';
    const t = ds ? new Date(ds).getTime() : NaN;
    const code = String(r.itemCode);
    if (!isFinite(t)) { latest[code] = Math.max(latest[code] || 0, Date.now()); continue; } // 日付不明行は安全側で除外対象に含める
    latest[code] = Math.max(latest[code] || 0, t);
  }
  postedCodes = Object.keys(latest).filter(c => latest[c] >= cutoff);
} catch (e) { /* 履歴なしとして続行 */ }

// item_pool: 直近7日のshop出現回数 / 直近3日の前日順位
const recentShops = {};
const prevRanks = {};
try {
  const rows = $('Read item_pool').all().map(i => i.json).filter(r => r && r.itemCode);
  const now = Date.now();
  for (const r of rows) {
    const t = r.date ? new Date(r.date).getTime() : 0;
    if (now - t <= 7 * 86400000 && r.shopCode) {
      recentShops[r.shopCode] = (recentShops[r.shopCode] || 0) + 1;
    }
    if (now - t <= 3 * 86400000 && r.rank !== undefined && r.rank !== '') {
      prevRanks[String(r.itemCode)] = Number(r.rank);
    }
  }
} catch (e) { /* 履歴なしとして続行 */ }

const jst = new Date(Date.now() + 9 * 3600000);
const today = jst.toISOString().slice(0, 10);
return [{ json: { params, postedCodes, recentShops, prevRanks, today } }];

// 6カテゴリ x 3クエリ = 18リクエスト
// genreId はREADME記載の通り「要確認」。誤っていればREADMEの手順で修正すること。
const ctx = $json;
// genreIdは要確認。Rakuten Ichiba Genre APIで確認すること。
const cats = [
  { key: 'gadget',           label: 'ガジェット・PC周辺機器',             genreId: '100026' },
  { key: 'stationery',       label: '高級文具・手帳',                     genreId: '215783' },
  { key: 'restaurant_supply',label: '飲食店向け厨房・業務用品',           genreId: '100533' },
  { key: 'beauty_salon',     label: '美容サロン向け機器・用品',           genreId: '551167' },
  { key: 'massage',          label: '整体・マッサージ向け機器',           genreId: '100939' }
];
const baseRanking = 'https://openapi.rakuten.co.jp/ichibaranking/api/IchibaItem';
const baseSearch = 'https://openapi.rakuten.co.jp/ichibams/api/IchibaItem';
const reqs = [];
for (const c of cats) {
  const pstar = ctx.params.pstar[c.key] || 6000;
  // (a) ランキングAPI
  reqs.push({ json: { category: c.key, label: c.label, reqType: 'ranking',
    url: `${baseRanking}/Ranking/20220601?format=json&genreId=${c.genreId}` } });
  // (b) 検索API レビュー数順
  reqs.push({ json: { category: c.key, label: c.label, reqType: 'review',
    url: `${baseSearch}/Search/20260701?format=json&genreId=${c.genreId}&sort=${encodeURIComponent('-reviewCount')}&hits=30` } });
  // (c) 検索API 価格帯指定（最適価格帯の0.6〜1.8倍）
  const minPrice = Math.round(pstar * 0.6);
  const maxPrice = Math.round(pstar * 1.8);
  reqs.push({ json: { category: c.key, label: c.label, reqType: 'price',
    url: `${baseSearch}/Search/20260701?format=json&genreId=${c.genreId}&minPrice=${minPrice}&maxPrice=${maxPrice}&sort=${encodeURIComponent('-reviewAverage')}&hits=30` } });
}
return reqs;

// 全ループ実行分のAPIレスポンスを回収し、itemCodeで一意化
// 楽天APIは Items/items, Item/item のキー大文字小文字が版により揺れるため両対応
const reqs = $('Build Requests').all().map(i => i.json);
const collected = [];
let run = 0;
while (run < reqs.length) {
  let items;
  try { items = $('Rakuten API Request').all(0, run); } catch (e) { break; }
  const meta = reqs[run] || {};
  for (const it of items) collected.push({ res: it.json, meta });
  run++;
}
const map = {};
for (const { res, meta } of collected) {
  if (!res || res.error) continue;
  const rawArr = Array.isArray(res.Items) ? res.Items : (Array.isArray(res.items) ? res.items : []);
  for (const w of rawArr) {
    const it = w.Item || w.item || w;
    const code = String(it.itemCode || '');
    if (!code) continue;
    let imageUrl = '';
    const imgs = it.mediumImageUrls;
    if (Array.isArray(imgs) && imgs.length) {
      const m = imgs[0];
      imageUrl = typeof m === 'string' ? m : (m.imageUrl || '');
    }
    const rec = {
      itemCode: code,
      itemName: String(it.itemName || ''),
      itemPrice: Number(it.itemPrice || 0),
      itemUrl: String(it.itemUrl || ''),
      affiliateUrl: String(it.affiliateUrl || ''),
      reviewCount: Number(it.reviewCount || 0),
      reviewAverage: Number(it.reviewAverage || 0),
      shopCode: String(it.shopCode || ''),
      shopName: String(it.shopName || ''),
      imageUrl,
      genreId: String(it.genreId || ''),
      availability: Number(it.availability !== undefined ? it.availability : 1),
      postageFlag: Number(it.postageFlag || 0),
      itemCaption: String(it.itemCaption || ''),
      rank: Number(it.rank || 0),
      category: meta.category,
      categoryLabel: meta.label
    };
    if (!map[code]) {
      map[code] = rec;
    } else if (rec.rank && !map[code].rank) {
      map[code].rank = rec.rank;
    }
  }
}
return Object.values(map).map(j => ({ json: j }));

// Hard Gate: 機械的除外条件 (Phase1: 条件緩和)
const ctx = $('Load Params & Defaults').first().json;
const posted = new Set(ctx.postedCodes || []);
const recentShops = ctx.recentShops || {};
const ngName = /中古|訳あり|福袋|ポイント消化/;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.reviewAverage < 3.0) continue;
  if (j.reviewCount < 1) continue;
  if (j.itemPrice < 500) continue;
  if (posted.has(j.itemCode)) continue;
  if ((recentShops[j.shopCode] || 0) >= 2) continue;
  if (ngName.test(j.itemName)) continue;
  out.push(item);
}
return out;

// Deterministic Score (f1..f6, f8)
const ctx = $('Load Params & Defaults').first().json;
const p = ctx.params;
const prevRanks = ctx.prevRanks || {};
// カテゴリ別推定料率（Phase1 初期値: 一律0.03）
const rates = { gadget: 0.03, stationery: 0.03, restaurant_supply: 0.03, beauty_salon: 0.03, massage: 0.03 };
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const rate = rates[j.category] || 0.03;
  const reward = Math.min(j.itemPrice * rate, 1000);
  const f1 = reward / 1000;
  const f2 = Math.min(Math.log10(1 + j.reviewCount) / Math.log10(3001), 1);
  const f3 = clamp((j.reviewAverage - 3.5) / 1.5, 0, 1);
  const pstar = p.pstar[j.category] || 6000;
  const sigma = p.sigma || 0.55;
  const f4 = Math.exp(-Math.pow(Math.log(j.itemPrice) - Math.log(pstar), 2) / (2 * Math.pow(sigma, 2)));
  const prev = prevRanks[j.itemCode];
  const f5 = (prev !== undefined && j.rank > 0) ? clamp((prev - j.rank) / 15, 0, 1) : 0.7; // 前日データ無し(新規)は0.7
  const f6 = 0.5; // Phase1: カテゴリ実績データ無しのため固定
  const f8 = 0.5; // Phase1: 季節性固定
  const num = p.w1 * f1 + p.w2 * f2 + p.w3 * f3 + p.w4 * f4 + p.w5 * f5 + p.w6 * f6 + p.w8 * f8;
  const den = p.w1 + p.w2 + p.w3 + p.w4 + p.w5 + p.w6 + p.w8;
  const baseScore = 100 * num / den;
  out.push({ json: { ...j, f1, f2, f3, f4, f5, f6, f8, baseScore: Math.round(baseScore * 100) / 100 } });
}
return out;

// baseScore降順で上位25件に絞る
const items = $input.all();
items.sort((a, b) => b.json.baseScore - a.json.baseScore);
return items.slice(0, 25);

// 25件を1回のAIコールでまとめて採点するためのペイロード構築
const items = $input.all().map(i => i.json);
const brief = items.map(j => ({
  itemCode: j.itemCode,
  name: j.itemName.slice(0, 80),
  price: j.itemPrice,
  category: j.categoryLabel,
  reviewCount: j.reviewCount,
  reviewAverage: j.reviewAverage,
  caption: (j.itemCaption || '').slice(0, 120)
}));
const prompt = items.length === 0 ? 'NO_CANDIDATES' :
  'あなたは個人店オーナー向け楽天アフィリエイト商品の目利きです。ターゲットは飲食店・美容サロン・整体院などの個人店オーナー。' +
  '以下の商品リストの各商品について、ターゲット適合度 aiFit（0〜1の数値）と、購買意欲を引く1文の hook を付けてください。' +
  '出力は必ずJSON配列のみ。各要素は {"itemCode":"...","aiFit":0.0,"hook":"..."} の形式。説明文・コードブロック記号は一切不要。\n\n商品リスト:\n' +
  JSON.stringify(brief);
return [{ json: { items, prompt } }];

// AI採点結果のパース。失敗時は aiFit=0.5 フォールバック
const payload = $('Prepare AI Payload').first().json;
const items = payload.items || [];
const fits = {};
try {
  const res = $input.first().json;
  const text = (res && res.content && res.content[0] && res.content[0].text) ? res.content[0].text : '';
  const m = text.match(/\[[\s\S]*\]/);
  const arr = JSON.parse(m ? m[0] : text);
  for (const a of arr) {
    const fit = Number(a.aiFit);
    fits[String(a.itemCode)] = {
      aiFit: isFinite(fit) ? Math.max(0, Math.min(1, fit)) : 0.5,
      hook: String(a.hook || '')
    };
  }
} catch (e) { /* 全件フォールバック */ }
return items.map(j => ({ json: {
  ...j,
  aiFit: fits[j.itemCode] ? fits[j.itemCode].aiFit : 0.5,
  hook: fits[j.itemCode] ? fits[j.itemCode].hook : '',
  aiFallback: !fits[j.itemCode]
} }));

// Final Score & 枠割当（ε-greedy探索付き）
const ctx = $('Load Params & Defaults').first().json;
const p = ctx.params;
const items = $input.all().map(i => i.json);
const slots = { 1: ['gadget', 'stationery'], 2: ['restaurant_supply', 'beauty_salon'], 3: ['massage'] };
// 静的ペナルティ + finalScore（同日同カテゴリ分は選択時に加算）
for (const j of items) {
  const capBad = !j.itemCaption || j.itemCaption.length < 30;
  j.pen0 = 15 * (j.postageFlag === 1 ? 1 : 0) + 20 * (capBad ? 1 : 0);
  const s = p.w1 * j.f1 + p.w2 * j.f2 + p.w3 * j.f3 + p.w4 * j.f4 + p.w5 * j.f5 + p.w6 * j.f6 + p.w7 * j.aiFit + p.w8 * j.f8;
  j.score0 = 100 * s - j.pen0;
}
const catCount = {};
const out = [];
for (const slot of [1, 2, 3]) {
  const pool = items
    .filter(j => slots[slot].includes(j.category))
    .map(j => ({ ...j, finalScore: Math.round((j.score0 - 10 * (catCount[j.category] || 0)) * 100) / 100 }))
    .sort((a, b) => b.finalScore - a.finalScore);
  const eligible = pool.filter(j => j.finalScore >= 55);
  // コンプラゲート落ち時のフォールバック用に上位3件を候補として持つ
  let picks = eligible.slice(0, 3).map((j, idx) => ({ ...j, rankInSlot: idx + 1, is_exploration: false }));
  // ε=epsilon の確率で 45〜75 帯からランダム差し替え（探索枠）
  if (Math.random() < (p.epsilon !== undefined ? p.epsilon : 0.20)) {
    const band = pool.filter(j => j.finalScore >= 45 && j.finalScore <= 75);
    if (band.length) {
      const ex = band[Math.floor(Math.random() * band.length)];
      const rest = picks.filter(x => x.itemCode !== ex.itemCode).slice(0, 2)
        .map((j, i) => ({ ...j, rankInSlot: i + 2 }));
      picks = [{ ...ex, rankInSlot: 1, is_exploration: true }, ...rest];
    }
  }
  // 候補ゼロの枠は空にする（無理に埋めない）
  if (picks.length) {
    catCount[picks[0].category] = (catCount[picks[0].category] || 0) + 1;
    for (const j of picks) {
      j.slot = slot;
      out.push({ json: j });
    }
  }
}
return out;

// 枠別フォーマットでの投稿文生成を1回のAIコールにまとめる
const cands = $input.all().map(i => i.json);
const formats = {
  1: '朝枠=課題提起型。「昨日、◯◯で困った経営者へ」のように経営現場の課題から入る。',
  2: '昼枠=数字・比較・スペック型。具体的な数値・スペック・比較を軸に淡々と語る。',
  3: '夜枠=ストーリー型。「これを買った人の共通点」のように物語・人物像で語る。'
};
const list = cands.map(c => ({
  itemCode: c.itemCode,
  slot: c.slot,
  format: formats[c.slot],
  name: c.itemName.slice(0, 80),
  price: c.itemPrice,
  category: c.categoryLabel,
  reviewCount: c.reviewCount,
  reviewAverage: c.reviewAverage,
  hook: c.hook || ''
}));
const prompt = cands.length === 0 ? 'NO_CANDIDATES' :
  'あなたは経営者向けThreadsアカウントのコピーライターです。以下の各商品について、slotごとに指定されたformatでThreads投稿文を書いてください。\n' +
  '共通制約:\n' +
  '- 冒頭は必ず「#PR」で始める\n' +
  '- 本文は180〜320字\n' +
  '- 絵文字禁止\n' +
  '- URLは本文に一切含めない（後工程で末尾に1本だけ付与される）\n' +
  '- ターゲットは飲食店・美容サロン・整体院などの個人店オーナー\n' +
  '- 誇大表現（絶対・必ず・最安・日本一・No.1）禁止\n' +
  '- 薬機法NG表現（治る・治療・効く・効果がある・改善する・予防・痩せる・若返る・病気・症状）禁止\n' +
  '出力は必ずJSON配列のみ。各要素は {"itemCode":"...","slot":1,"text":"..."} の形式。説明文・コードブロック記号は不要。\n\n候補:\n' +
  JSON.stringify(list);
return [{ json: { candidates: cands, prompt } }];

// 生成コピーを候補にマージ。text欠損の候補はコンプラゲートでスキップされる
const payload = $('Prepare Copy Payload').first().json;
const cands = payload.candidates || [];
const texts = {};
try {
  const res = $input.first().json;
  const text = (res && res.content && res.content[0] && res.content[0].text) ? res.content[0].text : '';
  const m = text.match(/\[[\s\S]*\]/);
  const arr = JSON.parse(m ? m[0] : text);
  for (const a of arr) texts[String(a.itemCode) + '_' + String(a.slot)] = String(a.text || '');
} catch (e) { /* text無しのまま流す */ }
return cands.map(c => ({ json: { ...c, text: texts[String(c.itemCode) + '_' + String(c.slot)] || '' } }));

// Compliance Gate: 違反は自動修正せずスキップし、同一枠の次点候補にフォールバック
const cands = $input.all().map(i => i.json);
const yakki = /治る|治療|効く|効果がある|改善する|予防|痩せる|若返る|病気|症状/;
const kodai = /絶対|必ず|最安|日本一|No\.?1|ナンバーワン/;
const urlRe = /https?:\/\//g;
const bySlot = {};
for (const c of cands) {
  (bySlot[c.slot] = bySlot[c.slot] || []).push(c);
}
const out = [];
for (const slot of Object.keys(bySlot)) {
  const list = bySlot[slot].sort((a, b) => a.rankInSlot - b.rankInSlot);
  let chosen = null;
  for (const c of list) {
    const t = String(c.text || '').trim();
    if (!t) continue;
    if (!t.startsWith('#PR')) continue;            // 冒頭#PR必須
    if (yakki.test(t)) continue;                    // 薬機法NG
    if (kodai.test(t)) continue;                    // 誇大表現NG
    if (t.length > 480) continue;                   // 全体480字以内（URL付与後の余裕込み）
    if ((t.match(urlRe) || []).length > 0) continue; // 本文にURL不可（末尾付与で計1本にする）
    chosen = c;
    break;
  }
  if (chosen) out.push({ json: chosen });
  // 全候補が違反した枠は空のまま（無理に埋めない）
}
return out;

// 計測ID付与 + post_queue行の組み立て
const jst = new Date(Date.now() + 9 * 3600000);
const dateStr = jst.toISOString().slice(0, 10);
const ymd = dateStr.replace(/-/g, '');
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const tail = String(j.itemCode).slice(-6).replace(/[^A-Za-z0-9]/g, '');
  const trackingId = `t705_${ymd}_s${j.slot}_${tail}`;
  const base = j.affiliateUrl || j.itemUrl;
  const url = base + (base.includes('?') ? '&' : '?') + 't705=' + trackingId;
  const text = String(j.text).trim() + '\n\n' + url;
  out.push({ json: {
    post_id: `705_${ymd}_s${j.slot}`,
    date: dateStr,
    slot: j.slot,
    itemCode: j.itemCode,
    itemName: j.itemName,
    price: j.itemPrice,
    category: j.category,
    shopCode: j.shopCode || '',
    f1: j.f1, f2: j.f2, f3: j.f3, f4: j.f4, f5: j.f5, f6: j.f6, f7: j.aiFit, f8: j.f8,
    baseScore: j.baseScore,
    aiFit: j.aiFit,
    finalScore: j.finalScore,
    is_exploration: j.is_exploration === true,
    text,
    url,
    tracking_id: trackingId,
    status: 'ready'
  } });
}
return out;

// item_pool 追記行（スコア済み全件を記録し、翌日以降のf5突合・shop重複判定に使う）
const jst = new Date(Date.now() + 9 * 3600000);
const dateStr = jst.toISOString().slice(0, 10);
return $input.all().map(i => {
  const j = i.json;
  return { json: {
    date: dateStr,
    itemCode: j.itemCode,
    rank: j.rank || '',
    price: j.itemPrice,
    reviewCount: j.reviewCount,
    reviewAverage: j.reviewAverage,
    shopCode: j.shopCode,
    category: j.category,
    baseScore: j.baseScore
  } };
});

// 実行サマリーとエラー判定
let queued = 0;
try { queued = $('Build Tracking URL & Queue Rows').all().length; } catch (e) {}
const errors = [];
if (queued === 0) errors.push('post_queue 追加0件（候補ゼロ・AI失敗・コンプラ全落ちの可能性）');
try {
  if ($('Parse AI Scores').all().some(i => i.json.aiFallback)) {
    errors.push('AI採点フォールバック発生（aiFit=0.5適用）');
  }
} catch (e) {}
try {
  const appended = $('Append post_queue').all();
  if (appended.some(i => i.json && i.json.error)) errors.push('post_queue への書き込みエラー');
} catch (e) { errors.push('post_queue への書き込みエラー'); }
const message = `DEV_RIO_705A 実行結果: キュー追加 ${queued}件` + (errors.length ? `\n⚠️ ${errors.join(' / ')}` : '');
return [{ json: { hasError: errors.length > 0, message } }];
